import{_ as a,o as t,c as s,a2 as o}from"./chunks/framework.DhQimoSI.js";const k=JSON.parse('{"title":"Packing a dataset","description":"","frontmatter":{},"headers":[],"relativePath":"tools/pack.md","filePath":"tools/pack.md"}'),i={name:"tools/pack.md"};function c(n,e,d,h,p,r){return t(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="packing-a-dataset" tabindex="-1">Packing a dataset <a class="header-anchor" href="#packing-a-dataset" aria-label="Permalink to &quot;Packing a dataset&quot;">​</a></h1><p>A Mosaic dataset is authored as one JSON document — the index plus the component rows — and packed into a <code>.tsr</code> archive for consumers:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mosaic</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pack</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">input.jso</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [output.tsr]</span></span></code></pre></div><p>Packing resolves each <code>componentTables[].schema</code> reference (a path relative to the source document) into the schema document itself, writes one <code>&lt;type&gt;.ndjson</code> file per component table, and puts them alongside <code>index.json</code> in the archive. Without an output path the archive is written next to the source document, so <code>house-v1.mosaic.json</code> becomes <code>house-v1.tsr</code>.</p><p>The source-document format is described in <a href="https://github.com/tomvandig/mosaic/blob/main/sdk/ts/test-data/README.md" target="_blank" rel="noreferrer"><code>sdk/ts/test-data/README.md</code></a>, and the packing itself lives in the TypeScript SDK (<code>buildMosaicFile</code>, <code>packMosaicSource</code>, <code>packMosaicSourceFile</code>), which the CLI depends on — so the same behaviour is available to any consumer of the SDK.</p>',5)])])}const u=a(i,[["render",c]]);export{k as __pageData,u as default};
